    setText(h > 0 ? `${h}h ${m}m` : m > 0 ? `${m}m ${s}s` : `${s}s`);
  };
  update();
  const id = setInterval(update, 1000);
  return () => clearInterval(id);
}, [targetDate]);
return text;

React.useEffect(() => {
  // ── ID resolution: sessionId is the live-session doc ID; classId is the class doc ID.
  // recordJoin writes liveSessionId = cls.sessionId || cls.id (the live-session ID).
  // checkStudentAttendance MUST query with the same ID, so prefer sessionId.
  const attCheckId = cls.sessionId || cls.liveSessionId || cls.id || cls.classId;
  const fallbackClassId = cls.classId || cls.id;
  console.log('[ATT-DEBUG] SessionCard mount — resolved IDs for attendance check:', {
    'cls.id': cls.id,
    'cls.classId': cls.classId,
    'cls.sessionId': cls.sessionId,
    'cls.liveSessionId': cls.liveSessionId,
    'attCheckId (used for new-att)': attCheckId,
    'fallbackClassId (used for lms-att)': fallbackClassId,
    title: cls.title || cls.className,
  });
  if (!attCheckId) {
    console.warn('[ATT-DEBUG] attCheckId is empty — skipping attendance check');
    return;
  }
  console.log('[ATT-DEBUG] Calling NewAttendanceApi.checkStudentAttendance with id:', attCheckId);
  import('../core/services').then(({ NewAttendanceApi, LmsAttendanceApi }) => {
    NewAttendanceApi.checkStudentAttendance(attCheckId)
      .then((res: any) => {
        const data = res?.data?.data || res?.data || {};
        console.log('[ATT-DEBUG] checkStudentAttendance response for', attCheckId, ':', data);
        if (data?.joined) {
          console.log('[ATT-DEBUG] ✅ Student HAS joined (new-attendance) — joinedAt:', data.joinedAt);
          setHasJoined(true);
          setAttRecord({ joinedAt: data.joinedAt || new Date().toISOString() });
        } else {
          console.log('[ATT-DEBUG] Not in new-attendance — falling back to LmsAttendanceApi for classId:', fallbackClassId);
          LmsAttendanceApi.getClassAttendance(fallbackClassId)
            .then((r: any) => {
              const rec = r?.data?.data || r?.data || null;
              console.log('[ATT-DEBUG] LmsAttendanceApi.getClassAttendance response:', rec);
              setAttRecord(rec);
              if (rec?.joinedAt) {
                console.log('[ATT-DEBUG] ✅ Student found in lms-attendance joinedAt:', rec.joinedAt);
                setHasJoined(true);
              } else {
                console.log('[ATT-DEBUG] ❌ No record in either attendance system');
              }
            })
            .catch((e: any) => console.warn('[ATT-DEBUG] LmsAttendanceApi.getClassAttendance failed:', e?.message));
        }
      })
      .catch((e: any) => {
        console.warn('[ATT-DEBUG] checkStudentAttendance failed:', e?.message, '— falling back to LmsAttendanceApi');
        LmsAttendanceApi.getClassAttendance(fallbackClassId)
          .then((r: any) => {
            const rec = r?.data?.data || r?.data || null;
            console.log('[ATT-DEBUG] Fallback LmsAttendanceApi response:', rec);
            setAttRecord(rec);
            if (rec?.joinedAt) {
              console.log('[ATT-DEBUG] ✅ Student found in fallback lms-attendance');
              setHasJoined(true);
            }
          })
          .catch((e2: any) => console.warn('[ATT-DEBUG] Fallback LmsAttendanceApi also failed:', e2?.message));
      });
  });
}, [cls.classId, cls.id, cls.sessionId, cls.liveSessionId]);

useEffect(() => {
  let fallbackTimer: ReturnType<typeof setInterval> | null = null;

  const startFallbackPolling = () => {
    if (fallbackTimer) return; // already polling
    console.info('[LiveDashboard] Firestore signal unavailable — starting 30s fallback polling.');
    fallbackTimer = setInterval(() => {
      queryClient.invalidateQueries({ queryKey: ['studentDashboard'] });
    }, 30_000);
  };

  const stopFallbackPolling = () => {
    if (fallbackTimer) {
      clearInterval(fallbackTimer);
      fallbackTimer = null;
      console.info('[LiveDashboard] Firestore signal restored — stopped fallback polling.');
    }
  };

  const unsub = onSnapshot(
    doc(db, 'live_class_index', 'current'),
    (_snap) => {
      // Signal doc exists and is reachable — stop fallback polling if running
      stopFallbackPolling();
      queryClient.invalidateQueries({ queryKey: ['studentDashboard'] });
    },
    (error) => {
      console.warn('[LiveDashboard] Firestore signal listener error:', error.code);
      // Start 30s fallback so students still get auto-refresh
      startFallbackPolling();
    }
  );

  return () => {
    unsub();
    stopFallbackPolling();
  };
}, [queryClient]);

useEffect(() => {
  LiveClassesApi.getMyAccessRequests()
    .then((res: any) => {
      const data = res?.data?.data || res?.data || [];
      setMyRequests(Array.isArray(data) ? data : []);
    })
    .catch(() => {});
}, []);

useEffect(() => {
  if (!targetDate) return;
  const update = () => {
    const diff = new Date(targetDate).getTime() - Date.now();
    if (diff <= 0) { setText('Starting now'); return; }
    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    setText(h > 0 ? `${h}h ${m}m` : m > 0 ? `${m}m ${s}s` : `${s}s`);
  };
  update();
  const id = setInterval(update, 1000);
  return () => clearInterval(id);
}, [targetDate]);
return text;

useEffect(() => {
  if (status?.qrCodeEnabled && timeLeft > 0) {
    if (timerRef.current) clearInterval(timerRef.current);

    const enabledAtTime = new Date(status.qrCodeEnabledAt).getTime();
    const durationMs = status.timerDuration * (status.timerUnit === 'minutes' ? 60 : 3600) * 1000;
    const expiryTime = enabledAtTime + durationMs;

    timerRef.current = setInterval(() => {
      const now = Date.now();
      const diff = Math.max(0, Math.floor((expiryTime - now) / 1000));

      setTimeLeft(diff);

      if (diff <= 0) {
        if (timerRef.current) clearInterval(timerRef.current);
        // Set qrCodeEnabled to false locally so page updates
        setStatus((prev: any) => ({ ...prev, qrCodeEnabled: false }));
        if (Platform.OS === 'web') {
          success("The payment QR code session has expired.");
        } else {
          Alert.alert("Expired", "The payment QR code session has expired.");
        }
      }
    }, 1000);
  }

  return () => {
    if (timerRef.current) clearInterval(timerRef.current);
  };
}, [status?.qrCodeEnabled, timeLeft, status?.qrCodeEnabledAt]);

useEffect(() => {
  let unsubStudent: (() => void) | null = null;
  let unsubPayments: (() => void) | null = null;
  try {
    if (typeof localStorage !== 'undefined') {
      const storedUser = JSON.parse(localStorage.getItem('nermai_auth_user') || '{}');
      const studentDocId = storedUser?.studentId || storedUser?.id || storedUser?.userId;
      if (studentDocId) {
        unsubStudent = onSnapshot(doc(db, 'students', studentDocId), () => {
          fetchQrStatus();
        }, (err) => {
          console.warn('[StudentPayFeesPage] Realtime student sync error:', err);
        });

        // Scope payment listener strictly to this student to prevent academy-wide read multiplier
        const qPayments = query(collection(db, 'payment_acknowledgements'), where('studentId', '==', studentDocId));
        unsubPayments = onSnapshot(qPayments, () => {
          fetchPaymentHistory();
        }, (err) => {
          console.warn('[StudentPayFeesPage] Realtime payment sync error:', err);
        });
      }
    }
  } catch (e) {}

  const unsubSettings = onSnapshot(doc(db, 'system_settings', 'payment_qr_code'), () => {
    fetchQrStatus();
  }, (err) => {
    console.warn('[StudentPayFeesPage] Realtime qr settings sync error:', err);
  });

  return () => {
    if (unsubStudent) unsubStudent();
    unsubSettings();
    if (unsubPayments) unsubPayments();
  };
}, []);
